package solution

import (
	"math"
	"testing"
)

func TestRingAreaUsesDifferenceOfCircleAreasAndRounds(t *testing.T) {
	cases := []struct {
		outer float64
		inner float64
		want  float64
	}{
		{2, 1, 9.42},
		{5, 3, 50.27},
		{1, 0, 3.14},
		{0.1, 0, 0.03},
	}
	for _, tc := range cases {
		got, err := RingArea(tc.outer, tc.inner)
		if err != nil || got != tc.want {
			t.Errorf("RingArea(%v, %v) = %v, %v; want %v, nil", tc.outer, tc.inner, got, err, tc.want)
		}
	}
}

func TestRingAreaEqualAndZeroRadii(t *testing.T) {
	for _, radius := range []float64{0, 1.5, 100} {
		got, err := RingArea(radius, radius)
		if err != nil || got != 0 {
			t.Errorf("RingArea(%v, %v) = %v, %v; want 0, nil", radius, radius, got, err)
		}
	}
	got, err := RingArea(math.Copysign(0, -1), 0)
	if err != nil || got != 0 {
		t.Errorf("RingArea(-0, 0) = %v, %v; want 0, nil", got, err)
	}
}

func TestRingAreaRejectsInvalidRadii(t *testing.T) {
	invalid := []struct {
		outer float64
		inner float64
	}{
		{-1, 0},
		{1, -1},
		{1, 2},
		{math.NaN(), 0},
		{1, math.NaN()},
		{math.Inf(1), 0},
		{1, math.Inf(1)},
		{math.Inf(-1), 0},
		{1, math.Inf(-1)},
	}
	for _, tc := range invalid {
		got, err := RingArea(tc.outer, tc.inner)
		if err == nil || got != 0 {
			t.Errorf("RingArea(%v, %v) = %v, %v; want 0 and error", tc.outer, tc.inner, got, err)
		}
	}
}

